import { createEffect, onCleanup } from "solid-js";
import { register } from "./register.js";

// The shape of @solid-primitives/timer's createTimer: a numeric delay
// registers a cleanup and returns; an accessor delay creates an effect.
export function useTicker(fn, delay) {
  if (typeof delay === "number") {
    register(fn, delay);
    return;
  }
  createEffect(() => delay(), () => fn());
}

export function useMaybe(flag, fn) {
  if (flag) onCleanup(fn);
}

// The package schedules the callback itself: running it unowned is the
// package's doing, whatever owner its caller has.
export function useLater(fn) {
  setTimeout(() => onCleanup(fn));
}

function cleanupNow() {
  onCleanup(() => {});
}

// One cleanup runs for every boolean input, from a different call site.
export function choice(flag) {
  if (flag) cleanupNow();
  if (!flag) cleanupNow();
}

// The cleanup runs after an `await`: unowned whatever the caller's owner.
export async function later() {
  await Promise.resolve();
  onCleanup(() => {});
}
